UPDATE tools SET long_description = E'Landingi, c''est création de landing pages no-code avec A/B testing. À partir de 25.11€/mois. Particulièrement pertinent pour les fondateurs SaaS et les developpeur-solo.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : 3+ campagnes marketing par mois avec A/B testing ou gestion de 10+ landing pages simultanément. À éviter si : 1-2 landing pages simples ou budget <29$/mois. Si vous lancez 3+ campagnes marketing par mois avec A/B testing. Alternative gratuite à considérer : carrd.', long_description_en = E'Landingi is no-code landing page creation with A/B testing. Starting at €25.11/month. Most relevant for SaaS founders and solo developers.\n\nEstimated time saving: 5h/month with regular use.\n\nKeep it if: 3+ marketing campaigns per month with A/B testing or management of 10+ landing pages simultaneously. Skip it if: 1-2 simple landing pages or budget <$29/month. If you are launching 3+ marketing campaigns per month with A/B testing. Free alternative worth considering: carrd.' WHERE slug = 'landingi';
